import os,http.server,socketserver
class H(http.server.SimpleHTTPRequestHandler):
 extensions_map={**http.server.SimpleHTTPRequestHandler.extensions_map,'.js':'text/javascript','.css':'text/css','.json':'application/json'}
 def end_headers(self):
  self.send_header('Cache-Control','no-store, must-revalidate')
  super().end_headers()
class T(socketserver.ThreadingMixIn,socketserver.TCPServer):
 daemon_threads=True
 allow_reuse_address=True
port=int(os.environ.get('PORT','8000'))
print('serving on',port,flush=True)
T(('',port),H).serve_forever()
